<?php
declare(strict_types=1);
session_start();
const APP_NAME = 'eDiary';
$dbDir = dirname(__DIR__, 2) . DIRECTORY_SEPARATOR . 'ediary-data';
$dbFile = $dbDir . DIRECTORY_SEPARATOR . 'ediary.sqlite';
if (!is_dir($dbDir) && !mkdir($dbDir, 0750, true) && !is_dir($dbDir)) { http_response_code(500); exit('Cannot create the data directory. Check filesystem permissions.'); }
try {
    $pdo = new PDO('sqlite:' . $dbFile, null, null, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
    $pdo->exec('PRAGMA foreign_keys = ON'); $pdo->exec('PRAGMA journal_mode = WAL');
    $pdo->exec("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");
    $pdo->exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', is_pinned INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)");
    $pdo->exec('CREATE INDEX IF NOT EXISTS idx_notes_user_updated ON notes(user_id, updated_at)');
} catch (Throwable $e) { http_response_code(500); exit('Database initialization failed. Check that PDO_SQLITE is enabled and the data directory is writable.'); }
function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function csrf_token(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if (!hash_equals(csrf_token(), (string)($_POST['csrf'] ?? ''))) { http_response_code(419); exit('Invalid form token. Go back and retry.'); } }
function redirect_to(string $url = 'index.php') { header('Location: ' . $url); exit; }
function logged_in(): bool { return isset($_SESSION['user_id']) && is_int($_SESSION['user_id']); }
$userCount = (int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(); $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string)($_POST['action'] ?? '');
    if ($action === 'setup' && $userCount === 0) {
        $username = trim((string)($_POST['username'] ?? '')); $password = (string)($_POST['password'] ?? '');
        if (!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/', $username)) $error = '用户名需为 3–40 位，只能包含字母、数字、点、下划线和连字符。';
        elseif (strlen($password) < 12) $error = '密码至少需要 12 个字符。';
        else { $stmt=$pdo->prepare('INSERT INTO users(username,password_hash) VALUES(?,?)'); $stmt->execute([$username,password_hash($password,PASSWORD_DEFAULT)]); session_regenerate_id(true); $_SESSION['user_id']=(int)$pdo->lastInsertId(); $_SESSION['username']=$username; redirect_to(); }
    } elseif ($action === 'login') {
        $stmt=$pdo->prepare('SELECT id,username,password_hash FROM users WHERE username=?'); $stmt->execute([trim((string)($_POST['username'] ?? ''))]); $user=$stmt->fetch();
        if ($user && password_verify((string)($_POST['password'] ?? ''),$user['password_hash'])) { session_regenerate_id(true); $_SESSION['user_id']=(int)$user['id']; $_SESSION['username']=$user['username']; redirect_to(); }
        $error='用户名或密码不正确。';
    } elseif ($action === 'logout' && logged_in()) {
        $_SESSION=[]; if (ini_get('session.use_cookies')) { $p=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']); } session_destroy(); redirect_to();
    } elseif (logged_in()) {
        $uid=(int)$_SESSION['user_id'];
        if ($action === 'save_note') {
            $id=(int)($_POST['id'] ?? 0); $title=trim((string)($_POST['title'] ?? '')); $content=trim((string)($_POST['content'] ?? '')); $tags=trim((string)($_POST['tags'] ?? '')); $pinned=isset($_POST['is_pinned'])?1:0;
            if ($title==='') $error='请填写笔记标题。';
            elseif (function_exists('mb_strlen') ? mb_strlen($title,'UTF-8')>200 : strlen($title)>600) $error='标题不能超过 200 个字符。';
            else { if ($id>0) { $stmt=$pdo->prepare('UPDATE notes SET title=?,content=?,tags=?,is_pinned=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?'); $stmt->execute([$title,$content,$tags,$pinned,$id,$uid]); } else { $stmt=$pdo->prepare('INSERT INTO notes(user_id,title,content,tags,is_pinned) VALUES(?,?,?,?,?)'); $stmt->execute([$uid,$title,$content,$tags,$pinned]); } redirect_to(); }
        } elseif ($action === 'delete_note') { $stmt=$pdo->prepare('DELETE FROM notes WHERE id=? AND user_id=?'); $stmt->execute([(int)($_POST['id'] ?? 0),$uid]); redirect_to();
        } elseif ($action === 'toggle_pin') { $stmt=$pdo->prepare('UPDATE notes SET is_pinned=1-is_pinned,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?'); $stmt->execute([(int)($_POST['id'] ?? 0),$uid]); redirect_to(); }
    }
}
$userCount=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(); $setupRequired=$userCount===0; $editNote=null; $notes=[]; $query=trim((string)($_GET['q'] ?? ''));
if (logged_in()) {
    $uid=(int)$_SESSION['user_id']; $editId=(int)($_GET['edit'] ?? 0);
    if ($editId>0) { $stmt=$pdo->prepare('SELECT * FROM notes WHERE id=? AND user_id=?'); $stmt->execute([$editId,$uid]); $editNote=$stmt->fetch() ?: null; }
    if ($query!=='') { $stmt=$pdo->prepare('SELECT * FROM notes WHERE user_id=? AND (title LIKE ? OR content LIKE ? OR tags LIKE ?) ORDER BY is_pinned DESC,updated_at DESC'); $like='%'.$query.'%'; $stmt->execute([$uid,$like,$like,$like]); }
    else { $stmt=$pdo->prepare('SELECT * FROM notes WHERE user_id=? ORDER BY is_pinned DESC,updated_at DESC'); $stmt->execute([$uid]); }
    $notes=$stmt->fetchAll();
}
?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e(APP_NAME) ?> · 个人电子笔记</title>
<style>
:root{--bg:#f5f6fa;--panel:#fff;--text:#202536;--muted:#788095;--line:#e8eaf1;--accent:#5c62d6;--soft:#eeefff;--shadow:0 10px 35px rgba(28,35,70,.06)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.6 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif}button,input,textarea{font:inherit}a{color:inherit;text-decoration:none;cursor:pointer}.topbar{height:68px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:5}.brand{font-weight:850;font-size:21px}.brand span{color:var(--accent)}.top-actions{display:flex;align-items:center;gap:12px}.muted{color:var(--muted)}.layout{max-width:1400px;margin:auto;padding:26px;display:grid;grid-template-columns:minmax(260px,330px) minmax(0,1fr);gap:24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}.editor{padding:22px;align-self:start;position:sticky;top:92px}.section-title{font-size:16px;font-weight:750;margin:0 0 16px}.field{display:block;width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 12px;background:#fff;color:var(--text);outline:none;margin:7px 0 15px}.field:focus{border-color:var(--accent);box-shadow:0 0 0 3px #5c62d61a}textarea.field{resize:vertical;min-height:250px}.label{font-size:13px;font-weight:650}.btn{border:0;border-radius:10px;background:var(--accent);color:#fff;padding:10px 15px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;gap:7px}.btn.secondary{background:var(--soft);color:var(--accent)}.btn.ghost{background:#f4f5f9;color:#525a70}.btn.full{width:100%}.checkrow{display:flex;align-items:center;gap:8px;margin:0 0 16px;font-size:13px;color:var(--muted)}.content-head{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:0 0 18px}.heading{font-size:25px;font-weight:800;letter-spacing:-.7px;margin:0}.search{display:flex;gap:8px;max-width:430px;width:100%}.search .field{margin:0}.note-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.note{padding:19px;min-width:0}.note-title{font-size:17px;font-weight:750;margin:0 0 8px;overflow-wrap:anywhere}.note-content{color:#626b7f;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden;min-height:40px}.tags{display:flex;flex-wrap:wrap;gap:6px;margin:13px 0}.tag{background:#f1f2f7;color:#626a7d;border-radius:6px;padding:3px 8px;font-size:12px}.note-foot{border-top:1px solid var(--line);padding-top:12px;margin-top:13px;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;color:var(--muted)}.note-actions{display:flex;gap:7px}.iconbtn{border:0;background:transparent;color:var(--muted);padding:3px 5px;font-size:12px}.iconbtn:hover{color:var(--accent)}.empty{padding:60px 24px;text-align:center;color:var(--muted);grid-column:1/-1}.empty strong{display:block;font-size:18px;color:var(--text);margin-bottom:6px}.alert{padding:11px 13px;border-radius:10px;margin-bottom:15px;background:#fff0f0;color:#a52f2f}.auth-wrap{min-height:calc(100vh - 100px);display:grid;place-items:center;padding:24px}.auth{width:min(440px,100%);padding:30px}.auth h1{margin-top:0}.hint{font-size:13px;color:var(--muted);margin-top:14px}.footer{text-align:center;color:var(--muted);font-size:12px;padding:10px 20px 28px}.smallform{display:inline}.smallform button{font-size:12px}
@media(max-width:900px){.layout{grid-template-columns:1fr;padding:16px}.editor{position:static}.note-grid{grid-template-columns:1fr 1fr}.content-head{align-items:flex-start;flex-direction:column}.search{max-width:none}}@media(max-width:560px){.topbar{padding:0 16px;height:62px}.layout{padding:12px;gap:14px}.note-grid{grid-template-columns:1fr}.editor{padding:17px}.heading{font-size:22px}.auth{padding:22px}}
</style></head><body>
<header class="topbar"><a class="brand" href="index.php">e<span>Diary</span></a><div class="top-actions"><?php if(logged_in()): ?><span class="muted"><?= e((string)$_SESSION['username']) ?></span><form method="post" class="smallform"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="logout"><button class="btn ghost" type="submit">退出</button></form><?php else: ?><span class="muted">你的私人知识空间</span><?php endif; ?></div></header>
<?php if($setupRequired): ?><section class="auth-wrap"><div class="panel auth"><h1>欢迎使用 eDiary</h1><p class="muted">首次使用，请创建管理员账户。密码至少 12 位。</p><?php if($error!==''): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="setup"><label class="label" for="username">管理员用户名</label><input class="field" id="username" name="username" required minlength="3" maxlength="40" autocomplete="username"><label class="label" for="password">管理员密码</label><input class="field" id="password" type="password" name="password" required minlength="12" autocomplete="new-password"><button class="btn full" type="submit">创建账户并开始使用</button></form><p class="hint">SQLite 文件保存在网站公开目录之外。</p></div></section>
<?php elseif(!logged_in()): ?><section class="auth-wrap"><div class="panel auth"><h1>欢迎回来</h1><p class="muted">登录以继续记录你的想法。</p><?php if($error!==''): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="login"><label class="label" for="username">用户名</label><input class="field" id="username" name="username" required autocomplete="username"><label class="label" for="password">密码</label><input class="field" id="password" type="password" name="password" required autocomplete="current-password"><button class="btn full" type="submit">登录</button></form><p class="hint">个人笔记仅在登录后可见。</p></div></section>
<?php else: ?><main class="layout"><aside class="panel editor"><h2 class="section-title"><?= $editNote?'编辑笔记':'写一条新笔记' ?></h2><?php if($error!==''): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_note"><input type="hidden" name="id" value="<?= (int)($editNote['id']??0) ?>"><label class="label" for="title">标题</label><input class="field" id="title" name="title" required maxlength="200" placeholder="给这条笔记起个标题" value="<?= e((string)($editNote['title']??'')) ?>"><label class="label" for="content">正文</label><textarea class="field" id="content" name="content" placeholder="记录想法、摘录、问题……"><?= e((string)($editNote['content']??'')) ?></textarea><label class="label" for="tags">标签</label><input class="field" id="tags" name="tags" placeholder="用逗号分隔，例如：读书, 灵感, 工作" value="<?= e((string)($editNote['tags']??'')) ?>"><label class="checkrow"><input type="checkbox" name="is_pinned" value="1" <?= !empty($editNote['is_pinned'])?'checked':'' ?>> 置顶这条笔记</label><button class="btn full" type="submit"><?= $editNote?'保存修改':'保存笔记' ?></button><?php if($editNote): ?><a class="btn ghost full" style="margin-top:8px" href="index.php">取消编辑</a><?php endif; ?></form><p class="hint">正文以纯文本安全保存；后续可扩展 Markdown 预览、卡片链接和知识图谱。</p></aside>
<section><div class="content-head"><div><h1 class="heading">我的笔记</h1><div class="muted"><?= count($notes) ?> 条<?= $query!==''?' · 搜索结果':' · 持续积累你的知识' ?></div></div><form class="search" method="get"><input class="field" name="q" placeholder="搜索标题、正文或标签…" value="<?= e($query) ?>"><button class="btn secondary" type="submit">搜索</button><?php if($query!==''): ?><a class="btn ghost" href="index.php">清除</a><?php endif; ?></form></div><div class="note-grid"><?php foreach($notes as $note): ?><article class="panel note"><h2 class="note-title"><?= !empty($note['is_pinned'])?'📌 ':'' ?><?= e($note['title']) ?></h2><div class="note-content"><?= e($note['content']) ?></div><?php $tagList=array_filter(array_map('trim',explode(',',(string)$note['tags']))); if($tagList): ?><div class="tags"><?php foreach($tagList as $tag): ?><span class="tag"><?= e($tag) ?></span><?php endforeach; ?></div><?php endif; ?><div class="note-foot"><span>更新于 <?= e($note['updated_at']) ?></span><div class="note-actions"><a class="iconbtn" href="index.php?edit=<?= (int)$note['id'] ?>">编辑</a><form method="post" class="smallform"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle_pin"><input type="hidden" name="id" value="<?= (int)$note['id'] ?>"><button class="iconbtn" type="submit"><?= !empty($note['is_pinned'])?'取消置顶':'置顶' ?></button></form><form method="post" class="smallform" onsubmit="return confirm('确定删除这条笔记吗？此操作不可撤销。')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_note"><input type="hidden" name="id" value="<?= (int)$note['id'] ?>"><button class="iconbtn" type="submit">删除</button></form></div></div></article><?php endforeach; ?><?php if(!$notes): ?><div class="panel empty"><strong><?= $query!==''?'没有找到匹配的笔记':'从第一条笔记开始' ?></strong><span><?= $query!==''?'换一个关键词试试。':'在左侧记录灵感、读书摘录或每日思考。' ?></span></div><?php endif; ?></div></section></main><?php endif; ?><footer class="footer">eDiary · PHP + SQLite · 你的笔记，由你掌控</footer></body></html>
